function InteractiveReader({data,footnotes=[],footnoteStyle={},onFootnoteOpen,initialNodeId,onProgress}) {
  const nodes=Array.isArray(data?.nodes)?data.nodes:[];
  const [nodeId,setNodeId]=useState(initialNodeId||data?.start||nodes[0]?.id);
  const scene=nodes.find(n=>n.id===nodeId)||nodes[0];
  const sceneRef=useRef(null);
  useEffect(()=>{if(initialNodeId&&nodes.some(n=>n.id===initialNodeId))setNodeId(initialNodeId);},[initialNodeId,data]);
  useEffect(()=>{onProgress?.(nodeId);},[nodeId]);
  useEffect(()=>{sceneRef.current?.scrollIntoView({behavior:'smooth',block:'start'});},[nodeId]);
  if(!scene)return <p>Сценарий интерактивной книги пока не настроен.</p>;
  const illustration=(url,alt)=>url?<figure className="reader-figure chapter-illustration"><img src={url} alt={alt||'Иллюстрация главы'}/>{alt&&<figcaption>{alt}</figcaption>}</figure>:null;
  const textBlocks=(scene.text||'').split(/\n\s*\n/);
  const embeddedImageUrls=textBlocks.map(block=>{const raw=block.trim();const markdown=raw.match(/^!\[([^\]]*)\]\((https?:\/\/[^\s)]+)\)$/);const plain=raw.match(/^(https?:\/\/[^\s<>"']+\.(?:png|jpe?g|webp|gif|bmp|avif)(?:[?#][^\s<>"']*)?)$/i);return markdown?.[2]||plain?.[1]||'';}).filter(Boolean);
  const startImageIsEmbedded=!!scene.image_start&&embeddedImageUrls.includes(scene.image_start);
  const endImageIsEmbedded=!!scene.image_end&&embeddedImageUrls.includes(scene.image_end);
  return <div className="interactive-reader" ref={sceneRef}><div className="interactive-scene"><div className="interactive-scene-label">ИНТЕРАКТИВНАЯ ГЛАВА</div><h2 className="reader-chapter-heading">{scene.title||scene.id}</h2>{!startImageIsEmbedded&&illustration(scene.image_start,scene.image_start_alt)}{textBlocks.map((block,i)=>{const raw=block.trim();const markdown=raw.match(/^!\[([^\]]*)\]\((https?:\/\/[^\s)]+)\)$/);const plain=raw.match(/^(https?:\/\/[^\s<>"']+\.(?:png|jpe?g|webp|gif|bmp|avif)(?:[?#][^\s<>"']*)?)$/i);const imageUrl=markdown?.[2]||plain?.[1];const alt=markdown?.[1]||'Иллюстрация главы';if(imageUrl)return <figure className="reader-figure chapter-illustration" key={i}><img src={imageUrl} alt={alt}/>{markdown?.[1]&&<figcaption>{alt}</figcaption>}</figure>;return <p key={i}>{block.split('\n').map((p,j)=><React.Fragment key={j}>{j>0&&<br/>}{renderFootnotedText(p,footnotes,footnoteStyle,onFootnoteOpen)}</React.Fragment>)}</p>;})}{!endImageIsEmbedded&&illustration(scene.image_end,scene.image_end_alt)}</div>{scene.choices?.length?<div className="interactive-choices"><div className="interactive-prompt">Что будете делать?</div>{scene.choices.map((choice,i)=><button key={i} style={{backgroundColor:choice.buttonColor||'#563b78',color:choice.textColor||'#fff'}} onClick={()=>{if(nodes.some(n=>n.id===choice.target))setNodeId(choice.target);}}>{choice.label}</button>)}</div>:<div className="interactive-ending"><b>Конец этой истории</b><button onClick={()=>setNodeId(data.start||nodes[0].id)}>Начать заново</button></div>}</div>;
}
function renderFootnotedText(text,footnotes=[],style={},onFootnoteOpen){
 const source=String(text??'');
 const entries=(footnotes||[]).map((f,i)=>({...f,_index:i,term:String(f.word||f.term||'').trim(),definition:String(f.text||f.note||'').trim()})).filter(f=>f.term&&f.definition).sort((a,b)=>b.term.length-a.term.length);
 if(!entries.length||!source)return source;
 const slash=String.fromCharCode(92);
 const specials='.*+?^$()|[]{}'+slash;
 const escapeRegex=value=>Array.from(value,ch=>specials.includes(ch)?slash+ch:ch).join('');
 const alternatives=entries.map(f=>escapeRegex(f.term)).join('|');
 const regex=new RegExp('(?<![A-Za-zА-Яа-яЁё0-9_])(?:'+alternatives+')(?![A-Za-zА-Яа-яЁё0-9_])','gi');
 const markerStyle={color:style.markerColor||'#f2c879',background:style.markerBackground||'#3a2c19',borderRadius:style.markerShape==='square'?'3px':'50%'};
 const result=[];
 let lastIndex=0,match;
 while((match=regex.exec(source))!==null){
  if(match.index>lastIndex)result.push(source.slice(lastIndex,match.index));
  const matchedText=match[0];
  const found=entries.find(f=>f.term.toLocaleLowerCase()===matchedText.toLocaleLowerCase());
  if(!found){result.push(matchedText);lastIndex=regex.lastIndex;continue;}
  const targetId='book-footnote-'+found._index;
  // Сохраняем сам элемент слова: кнопка возврата сможет прокрутить точно к нему.
  result.push(<a key={'footnote-'+found._index+'-'+match.index} className="footnote-word" href={'#'+targetId} title={'Нажми, чтобы открыть пояснение: '+found.definition} aria-label={matchedText+'. Перейти к пояснению '+(found._index+1)} onClick={e=>{e.preventDefault();onFootnoteOpen?.(e.currentTarget);document.getElementById(targetId)?.scrollIntoView({behavior:'smooth',block:'center'});}}><span className="footnote-word-text">{matchedText}</span><sup className="footnote-marker"><span style={markerStyle}>{found._index+1}</span></sup></a>);
  lastIndex=regex.lastIndex;
 }
 if(lastIndex<source.length)result.push(source.slice(lastIndex));
 return result;
}
function Footnotes({items,style={}}){
 const list=(items||[]).map((f,i)=>({...f,_index:i})).filter(f=>String(f.word||f.term||'').trim()&&String(f.text||f.note||'').trim());
 if(!list.length)return null;
 const s=style||{};
 return <section className="book-footnotes" style={{background:s.background||'#17151d',color:s.textColor||'#eee8dc',borderColor:s.borderColor||'#6f5a3b'}}><div className="interactive-scene-label" style={{color:s.titleColor||s.markerColor||'#c6a36a'}}>{s.title||'Сноски'}</div><ol>{list.map(f=><li id={'book-footnote-'+f._index} key={f._index} tabIndex={-1}><b>{f.word||f.term}</b><span>{f.text||f.note}</span></li>)}</ol></section>}
