async function toggleBookFavorite(bookId){if(!user){navigate('account');setNotice('Войди в аккаунт, чтобы добавлять книги в избранное.');return;}const id=String(bookId),exists=profileData.favoriteBooks.includes(id);const result=exists?await supabase.from('user_book_favorites').delete().eq('user_id',user.id).eq('book_id',bookId):await supabase.from('user_book_favorites').insert({user_id:user.id,book_id:bookId});if(result.error){setError(result.error.message);return;}setProfileData(v=>({...v,favoriteBooks:exists?v.favoriteBooks.filter(x=>x!==id):[...v.favoriteBooks,id]}));}
async function toggleCollectionFavorite(collectionId){if(!user){navigate('account');setNotice('Войди в аккаунт, чтобы сохранять коллекции.');return;}const id=String(collectionId),exists=profileData.favoriteCollections.includes(id);const result=exists?await supabase.from('user_collection_favorites').delete().eq('user_id',user.id).eq('collection_id',id):await supabase.from('user_collection_favorites').insert({user_id:user.id,collection_id:id});if(result.error){setError(result.error.message);return;}setProfileData(v=>({...v,favoriteCollections:exists?v.favoriteCollections.filter(x=>x!==id):[...v.favoriteCollections,id]}));}
async function persistReadingProgress(bookId,progress){
 const value={...(progress||{}),updatedAt:new Date().toISOString()};
 const key='bookcheef-reading-'+String(bookId);
 if(user&&supabase){
  const old=profileDataRef.current.history.find(x=>String(x.book_id)===String(bookId));
  const payload={user_id:user.id,book_id:bookId,last_opened_at:value.updatedAt,completed:!!old?.completed,completed_at:old?.completed_at||null,reading_progress:value};
  const {error}=await supabase.from('user_reading_history').upsert(payload,{onConflict:'user_id,book_id'});
  if(error){setError(error.message);return;}
  setProfileData(v=>({...v,history:[payload,...v.history.filter(x=>String(x.book_id)!==String(bookId))]}));
 }else{
  try{localStorage.setItem(key,JSON.stringify(value));}catch{}
 }
}
useEffect(()=>{
 if(page!=='detail'||!selected||!current)return;
 const identity=(user?.id||'guest')+':'+selected;
 if(restoreProgressKeyRef.current===identity)return;
 if(user&&profileLoading)return;
 let saved=null;
 try{saved=user?profileData.history.find(x=>String(x.book_id)===String(selected))?.reading_progress:JSON.parse(localStorage.getItem('bookcheef-reading-'+String(selected))||'null');}catch{}
 if(!saved)return;
 restoreProgressKeyRef.current=identity;
 requestAnimationFrame(()=>{if(Number.isFinite(Number(saved.scrollY)))window.scrollTo({top:Math.max(0,Number(saved.scrollY)),behavior:'auto'});});
},[page,selected,current,user,profileLoading,profileData.history]);
useEffect(()=>{
 if(page!=='detail'||!selected||!current)return;
 const bookId=selected;
 const onScroll=()=>{
  if(progressTimerRef.current)clearTimeout(progressTimerRef.current);
  progressTimerRef.current=setTimeout(()=>persistReadingProgress(bookId,{scrollY:window.scrollY}),1200);
 };
 window.addEventListener('scroll',onScroll,{passive:true});
 return()=>{window.removeEventListener('scroll',onScroll);if(progressTimerRef.current){clearTimeout(progressTimerRef.current);progressTimerRef.current=null;persistReadingProgress(bookId,{scrollY:window.scrollY});}};
},[page,selected,current,user]);
async function markBookRead(bookId){if(!user){navigate('account');setNotice('Войди в аккаунт, чтобы сохранять прогресс чтения.');return;}const now=new Date().toISOString(),old=profileData.history.find(x=>String(x.book_id)===String(bookId));const payload={user_id:user.id,book_id:bookId,last_opened_at:now,completed:true,completed_at:old?.completed_at||now,reading_progress:old?.reading_progress||{}};const {error}=await supabase.from('user_reading_history').upsert(payload,{onConflict:'user_id,book_id'});if(error){setError(error.message);return;}setProfileData(v=>({...v,history:[payload,...v.history.filter(x=>String(x.book_id)!==String(bookId))]}));setNotice('Книга добавлена в прочитанные.');}
async function rateBook(bookId,rating){if(!user){navigate('account');setNotice('Войди в аккаунт, чтобы оценивать книги.');return;}const {error}=await supabase.from('book_ratings').upsert({user_id:user.id,book_id:bookId,rating},{onConflict:'user_id,book_id'});if(error){setError(error.message);return;}setProfileData(v=>{const old=v.ratings.find(x=>String(x.book_id)===String(bookId))||{};return {...v,ratings:[...v.ratings.filter(x=>String(x.book_id)!==String(bookId)),{book_id:bookId,likes:Number(old.likes||0)-(old.my_rating===1?1:0)+(rating===1?1:0),dislikes:Number(old.dislikes||0)-(old.my_rating===-1?1:0)+(rating===-1?1:0),my_rating:rating}]}});setNotice(rating===1?'Тебе понравилась книга.':'Ты отметил книгу как не понравившуюся.');}
function bookRating(bookId){const rows=profileData.ratings.filter(x=>String(x.book_id)===String(bookId));const likes=Number(rows[0]?.likes)||0,dislikes=Number(rows[0]?.dislikes)||0,total=likes+dislikes;return {likes,dislikes,total,percent:total?Math.round(likes/total*100):0,mine:Number(rows[0]?.my_rating)||0};}
async function refreshSubscription(){const {data,error}=await supabase.rpc('get_my_subscription');if(error)throw error;const value=Array.isArray(data)?data[0]:data;setSubscription(value||{is_active:false,expires_at:null});}
async function redeemPromo(e){e.preventDefault();setError('');try{const {error}=await supabase.rpc('redeem_promo_code',{input_code:promoInput.trim()});if(error)throw error;setPromoInput('');await refreshSubscription();setSuccessDialog({title:'Промокод успешно активирован!',message:'Подписка Pro подключена. Теперь тебе доступны все книги Pro.'});}catch(e){setError(e.message||'Не удалось активировать промокод.');}}
